#!/usr/bin/env bash\nset -euo pipefail\n\n# ------------------------------------------------------------\n# Test suite for nightly-disk-usage-visualizer\n# ------------------------------------------------------------\n# The test creates a temporary directory structure and a mock\n# du script that returns predefined sizes.  By exporting DU_CMD we\n# force the utility to use the mock instead of the real du, making\n# the test fully deterministic and offline.\n# ------------------------------------------------------------\n\n# Create a temporary workspace\nTMP=$(mktemp -d)\ntrap 'rm -rf "$TMP"' EXIT\n\n# Create sub‑directories a, b, c\nmkdir -p "$TMP"/a "$TMP"/b "$TMP"/c\n\n# Mock du script – returns fixed sizes (in kilobytes)\ncat > "$TMP/mock_du.sh" <<'EOF'\n#!/usr/bin/env bash\ncase "$1" in\n  */a) echo -e "10\t$1" ;;\n  */b) echo -e "30\t$1" ;;\n  */c) echo -e "20\t$1" ;;\n  *) echo -e "0\t$1" ;;\nesac\nEOF\nchmod +x "$TMP/mock_du.sh"\n\n# Export the mock command so the utility uses it\nexport DU_CMD="$TMP/mock_du.sh"\n\n# Run the utility (depth 1 to only include a, b, c)\noutput=$(bash ../src/main.sh "$TMP" 1)\n\n# Verify that each directory appears with the correct size\necho "$output" | grep -E "^a[[:space:]]+10K" >/dev/null\necho "$output" | grep -E "^b[[:space:]]+30K" >/dev/null\necho "$output" | grep -E "^c[[:space:]]+20K" >/dev/null\n\n# Extract bar lengths (number of # characters)\nbar_len() {\n  echo "$1" | awk '{print $3}' | wc -c\n}\n\nlen_b=$(bar_len "$(echo "$output" | grep '^b')")\nlen_c=$(bar_len "$(echo "$output" | grep '^c')")\nlen_a=$(bar_len "$(echo "$output" | grep '^a')")\n\n# b should have the longest bar, a the shortest\nif (( len_b > len_c && len_c > len_a )); then\n  echo "All tests passed"\n  exit 0\nelse\n  echo "Bar length ordering incorrect"\n  exit 1\nfi\n
